nits"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-011"}]}, {"id": "FAM:SF-APPS-075", "label": "Study family SF-APPS-075: Extended Possession Value (direct PPP + opponent T+1 suppression)", "score": 1.215, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-075 (0.86)", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.76); FAM:SF-APPS-075 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Extended Possession Value (direct PPP + opponent T+1 suppression)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Play types and players have a real downstream (opponent next-PPP) component beyond direct PPP.", "observed_result": "4/8 PTs downstream real: CUT Ext 1.658 (supp +0.0220), TRANSITION 1.509 (+0.0145), SPOT_UP 1.303 (+0.0124), POST_UP 1.127 (+0.0194). DRIVE downstream not real (opp ATT +0.0024). Player downstream mostly BH ns except M. M [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Downstream effects are small (~0.01-0.02 PPP) relative to direct PPP gaps; player list is mostly non-FINDING after BH.", "observed_sample_and_power": "PT-level n in the tens to hundreds of thousands implied by other seq files"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-049"}, {"rel": "auto_related_family", "node": "FAM:SF07"}]}, {"id": "FAM:SF07", "label": "Study family SF07: Sequential pair premium and defensive aftershock (8/8 PTs)", "score": 1.199, "reached_via": ["FAM:SF-APPS-075 auto_related_family (record_link_related_to) FAM:SF07", "FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF07"], "attributes": {"observed_research_question": "Sequential pair premium and defensive aftershock (8/8 PTs)", "auto_outcome_status": "supported", "observed_hypothesis": "After the opponent r