"], "attributes": {"observed_research_question": "Persistent Impact Score Level 1 gate", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality).", "observed_result": "FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Flat non-decaying lifts collapse under within-team baseline; team-quality confound.", "observed_sample_and_power": "n>150k per lag; 915,570 possessions", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "failed_gate"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-073"}]}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.887, "reached_via": ["request matches RQC:RQC-053 (0.75); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-053", "FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF-APPA-058"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.821, "reached_via": ["request matches RQC:RQC-098 (0.74); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-098", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.76); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts.", "observed_sample_and_power": "n>=30 for lineup cells cited", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Jokic/Curry/Doncic/Giannis; min-15 gate on 8 play types; opposing DEFENSE_LINEUP ~84% coverage; 272-row CSV."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}], "n_results": 10}

