    {
      "id": "FAM:SF-APPS-049",
      "what_failed": "Hypothesis of durable conditional pivot branches (if-X-fails-then-Y)",
      "why": "adequately powered null: no durable branches found across 104 playoff team-offense units."
    },
    {
      "id": "FAM:SF-APPA-050",
      "what_failed": "Small-n sequential suppression per star without multiplicity control",
      "why": "n_after as low as 32; no adjustment for multiple comparisons; inability to distinguish signal from noise."
